import { AudioPlayer, createAudioPlayer, setAudioModeAsync } from "expo-audio";
import store from "../redux/reduxStore";

/**
 * Sound effects (generated by scripts/tools/generateSounds.js)
 *
 * Taps play a soft, quiet "plop", like the clicks in Cookie Clicker: one of a few
 * slightly different ones, never the same twice in a row. Shiny emojis get a
 * chime, buying a building a light "bling" and an upgrade a short sparkle. Off in Settings.
 */

const TAP_SOURCES = [
    require("../../assets/sounds/tap_0.wav"),
    require("../../assets/sounds/tap_1.wav"),
    require("../../assets/sounds/tap_2.wav"),
    require("../../assets/sounds/tap_3.wav"),
    require("../../assets/sounds/tap_4.wav"),
    require("../../assets/sounds/tap_5.wav"),
];
const SHINY_SOURCE = require("../../assets/sounds/shiny.wav");
const BUILDING_SOURCE = require("../../assets/sounds/building.wav");
const UPGRADE_SOURCE = require("../../assets/sounds/upgrade.wav");

const TAP_VOLUME = 0.3;
const SHINY_VOLUME = 0.7;
const PURCHASE_VOLUME = 0.6;
// Players per tap sound, so fast taps overlap instead of cutting each other off
const PLAYERS_PER_SOUND = 3;
// At most this many tap sounds a second, however fast the tapping
const MIN_TAP_GAP_MS = 55;

let tapPlayers: AudioPlayer[][] | undefined;
let shinyPlayer: AudioPlayer | undefined;
// Two each, so buying quickly in a row doesn't cut the last sound off
let buildingPlayers: AudioPlayer[] = [];
let upgradePlayers: AudioPlayer[] = [];
let lastSound = -1;
let lastTapAt = 0;

/** Players are made the first time a sound plays, not when the game loads */
function load() {
    if (tapPlayers) return;
    // Plays alongside the player's own music, and not when the phone is on silent.
    // Android has no "mix": duck just lowers other audio for a moment.
    setAudioModeAsync({ playsInSilentMode: false, interruptionMode: "mixWithOthers", interruptionModeAndroid: "duckOthers" }).catch(() => { });
    tapPlayers = TAP_SOURCES.map(source => Array.from({ length: PLAYERS_PER_SOUND }, () => {
        const player = createAudioPlayer(source);
        player.volume = TAP_VOLUME;
        return player;
    }));
    shinyPlayer = createAudioPlayer(SHINY_SOURCE);
    shinyPlayer.volume = SHINY_VOLUME;
    const purchase = (source: number) => Array.from({ length: 2 }, () => {
        const player = createAudioPlayer(source);
        player.volume = PURCHASE_VOLUME;
        return player;
    });
    buildingPlayers = purchase(BUILDING_SOURCE);
    upgradePlayers = purchase(UPGRADE_SOURCE);
}

/** A free player, or the one that has been playing longest */
function freePlayer(players: AudioPlayer[]) {
    return players.find(p => !p.playing) ?? players.reduce((a, b) => a.currentTime >= b.currentTime ? a : b);
}

function soundOn() {
    // Missing from saves made before it existed: on
    return store.getState().preferences.soundEffects ?? true;
}

function restart(player: AudioPlayer) {
    player.seekTo(0).catch(() => { });
    player.play();
}

/** A tap on the Big Emoji */
export function playTapSound() {
    if (!soundOn()) return;
    const now = Date.now();
    if (now - lastTapAt < MIN_TAP_GAP_MS) return;
    lastTapAt = now;
    load();

    // Any of them but the last one
    const sound = (lastSound + 1 + Math.floor(Math.random() * (TAP_SOURCES.length - 1))) % TAP_SOURCES.length;
    lastSound = sound;

    restart(freePlayer(tapPlayers![sound]));
}

/** Tapping a shiny emoji */
export function playShinySound() {
    if (!soundOn()) return;
    load();
    restart(shinyPlayer!);
}

/** Buying a building (one sound however many are bought at once) */
export function playBuildingSound() {
    if (!soundOn()) return;
    load();
    restart(freePlayer(buildingPlayers));
}

/** Buying an upgrade */
export function playUpgradeSound() {
    if (!soundOn()) return;
    load();
    restart(freePlayer(upgradePlayers));
}
